B.bcc=new A.jj('Ein Snapshot ist eine "eingefrorene" Momentaufnahme aller Lagerbest\xe4nde zu einem bestimmten Stichtag. Er enth\xe4lt die genauen Mengen pro Lagerort und Holzart \u2014 und bleibt f\xfcr immer unver\xe4ndert, auch wenn sich der aktuelle Bestand danach \xe4ndert.',null)
B.bbR=new A.jj("Snapshots sind besonders n\xfctzlich f\xfcr Jahres- und Quartalsabschl\xfcsse, f\xfcr Inventuren und um den Bestandsverlauf \xfcber l\xe4ngere Zeitr\xe4ume nachzuvollziehen.",null)
B.c_d=s([B.bcc,B.bbR],t.p)
B.bco=new A.r9("Was ist ein Snapshot?","info",B.db,B.c_d,null)
B.b6t=new A.jL("event",B.h6,"Jahresabschluss",'F\xfcr den Stichtag 31.12. eines Jahres. Wird automatisch mit dem Titel "Jahresabschluss [Jahr]" angelegt.',null,null)
B.b6s=new A.jL("event_note",B.AX,"Quartalsabschluss",'F\xfcr ein Quartal \u2014 z.B. "Q3 2025". Das richtige Quartal wird aus dem Stichtag automatisch ermittelt.',null,null)
B.b6x=new A.jL("fact_check",B.AY,"Inventur",'Beliebiger Stichtag f\xfcr eine Bestandspr\xfcfung. Wird mit Datum betitelt: "Inventur 15.08.2025".',null,null)
B.b6F=new A.jL("tune",B.k4,"Sonstiges","Frei w\xe4hlbarer Titel \u2014 z.B. vor einer Software-Umstellung oder einer externen Pr\xfcfung.",null,null)
